const initial=()=>({pos:new T.Vector3(0,1.7,15),yaw:0,pitch:0,mode:'bike',battery:16,drone:100,hp:100,speed:0,temp:24,inv:{wire:0,cells:0,electronics:0,steel:0},ammo:12,controller:false,interface:false,upgrade:false,solar:false,relay:false,met:false,scanned:false,ev:36,solarEnergy:48,gridEnergy:70,won:false,dead:false});let s=initial(),paused=true,screen='start',keys={},nearest=null,toastTimer=0,shotCooldown=0,enemyTimer=0,last=performance.now(),time=0,droneOrigin=null,flash=0;
const sites=[{id:'camp',name:'MARA / SURVIVOR CAMP',x:54,z:-94,y:3,color:'#d3e9c1'},{id:'ev',name:'STRANDED EV',x:-85,z:-290,y:4,color:'#dceba0'},{id:'solar',name:'SOLAR YARD',x:90,z:-416,y:5,color:'#dceba0'},{id:'grid',name:'DARK SUBSTATION',x:155,z:-733,y:7,color:'#dceba0'},{id:'relay',name:'DRONE RELAY',x:166,z:-778,y:15,color:'#9ae4df'},{id:'tower',name:'RADIO TOWER',x:0,z:-1439,y:25,color:'#e8f18c'}];sites.forEach(p=>{p.el=document.createElement('div');p.el.className='marker';$('#markers').append(p.el);});
const weights={wire:.3,cells:1.2,electronics:.5,steel:1.8};const cargo=()=>Object.entries(s.inv).reduce((a,[k,v])=>a+weights[k]*v,0);const dist=(x,z)=>Math.hypot(s.pos.x-x,s.pos.z-z);function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';toastTimer=4.5;}function radio(t){$('#radioText').textContent=t;}
function spend(n){if(s.battery<n){toast('Insufficient bike charge. Locate an energy source.');return false;}s.battery-=n;return true;}
function can(cost){return Object.entries(cost).every(([k,n])=>s.inv[k]>=n);}function take(cost){Object.entries(cost).forEach(([k,n])=>s.inv[k]-=n);}function add(items){Object.entries(items).forEach(([k,n])=>s.inv[k]+=n);}
function open(type){screen=type;paused=true;keys={};document.exitPointerLock?.();$('#overlay').style.display='flex';renderPanel();}function play(){paused=false;screen='';$('#overlay').style.display='none';if(matchMedia('(pointer:fine)').matches)$('#world').requestPointerLock?.()?.catch?.(()=>{});last=performance.now();}
const recipes=[{id:'controller',title:'Repair solar controller',desc:'2 wire + 2 electronics · unlock solar harvesting',cost:{wire:2,electronics:2}},{id:'interface',title:'Restore grid coupler',desc:'2 wire + 1 electronics · fictional substation interface',cost:{wire:2,electronics:1}},{id:'module',title:'Recondition battery module',desc:'2 cells + 1 electronics · recover 22% bike charge',cost:{cells:2,electronics:1}},{id:'upgrade',title:'Fit efficient motor controller',desc:'2 electronics + 2 steel · 30% less riding energy',cost:{electronics:2,steel:2}},{id:'repair',title:'Patch bike & armor',desc:'1 steel · restore 35% hull',cost:{steel:1}}];
function craft(id){const r=recipes.find(r=>r.id===id);if(!r||!can(r.cost))return;if(['controller','interface','upgrade'].includes(id)&&s[id])return;if(id==='module'&&s.battery>78){toast('Use some charge before reconditioning this module.');return;}if(id==='repair'&&s.hp>=100)return;take(r.cost);if(id==='module')s.battery=clamp(s.battery+22,0,100);else if(id==='repair')s.hp=clamp(s.hp+35,0,100);else s[id]=true;toast(r.title+' / COMPLETE');renderPanel();}
function renderPanel(){let html='';if(screen==='start')html=`<div class="eyebrow">FIRST PLAYABLE / SECTOR 07</div><h1>GRID<span>RUNNER</span></h1><p class="lead">The grid is dead. Something is still transmitting.</p><p class="lead">Your bike has 16% charge. The relay is 2.9 km north. Scout the ruins, recover electricity, and find out who is keeping the lights on.</p><div class="chips"><span>FPV RIDING</span><span>DRONE RECON</span><span>ENERGY SURVIVAL</span></div><button class="primary" data-panel="play">ENTER THE WASTELAND</button><div class="controls">WASD move · Mouse or arrows look · F mount / dismount<br>Q drone · E interact · R scan · I inventory · M map<br>Click or X fire · Space / Shift drone altitude<br>On touch: use the directional pad and drag the world to look.<br>Escape pauses. This expedition stays in this tab; restarting resets it.</div>`;
else if(screen==='inventory')html=`<div class="panelTop"><div><div class="eyebrow">FIELD EQUIPMENT</div><h2>Pack & workshop</h2></div><button data-panel="play">CLOSE ×</button></div><p class="hint">${cargo().toFixed(1)} / 24 KG · ${s.ammo} ballistic rounds · ${s.upgrade?'EFFICIENT MOTOR FITTED':'STANDARD MOTOR'}</p><div class="grid">${Object.entries(s.inv).map(([k,v])=>`<div class="item"><b>${k.toUpperCase()} × ${v}</b>${(weights[k]*v).toFixed(1)} kg <button data-drop="${k}" ${v?'':'disabled'} title="Drop one ${k}">−</button></div>`).join('')}<div class="item"><b>SOLAR CONTROLLER</b>${s.controller?'REPAIRED':'MISSING'}</div><div class="item"><b>GRID COUPLER</b>${s.interface?'RESTORED':'DAMAGED'}</div></div>${recipes.map(r=>`<div class="recipe"><div><strong>${r.title}</strong><p>${r.desc}</p></div><button data-craft="${r.id}" ${!can(r.cost)||s[r.id]||(r.id==='repair'&&s.hp>=100)||(r.id==='module'&&s.battery>78)?'disabled':''}>${s[r.id]?'FITTED':'CRAFT'}</button></div>`).join('')}<div class="recipe"><div><strong>Recharge drone from bike</strong><p>10% bike → up to 50% drone</p></div><button data-panel="transfer" ${s.battery<10||s.drone>=100?'disabled':''}>TRANSFER</button></div><p class="hint">More cargo increases riding consumption. Crafting repairs existing hardware.</p>`;
else if(screen==='map')html=`<div class="panelTop"><div><div class="eyebrow">HELMET NAVIGATION</div><h2>Sector 07 / The line</h2></div><button data-panel="play">CLOSE ×</button></div><canvas class="mapCanvas" id="bigmap" width="640" height="540"></canvas><p class="hint">North is up. Pale circles: known sites. Red: hostile patrols after a drone scan. World distances are compressed 2:1 for this slice.</p>`;
else if(screen==='npc')html=`<div class="eyebrow">MARA / FIELD ENGINEER</div><h2>“Electricity always leaves a trail.”</h2><p class="lead">That tower has been calling for twelve years. Yesterday, the message changed.</p><p>There’s a stranded EV west of the road. Its emergency pack still has charge. The solar yard needs a controller: search the crates, then repair one in your pack.</p><p>The substation has a bigger reserve. Restore your grid coupler and fly your drone up to the relay on the roof. That will release the charge cabinet.</p><p class="hint">I’ve given you 1 electronics board, 2 steel, and the repair schematics. Raiders patrol the highway. Circle around them or make your shots count.</p><button class="primary" data-panel="play">FOLLOW THE LINE</button>`;
else if(screen==='win')html=`<div class="eyebrow">RELAY UPLINK / DECRYPTED</div><h1>NEW SIGNAL<br><span>ACQUIRED</span></h1><p class="lead">This tower is only a relay. The transmission is coming from a facility far beyond the local grid.</p><div class="chips"><span>DISTANCE: 147 KM</span><span>ORIGIN: UNKNOWN</span></div><p>“Black start successful. Corridor seven remains active. Awaiting your arrival.”</p><p class="hint">Vertical slice complete · Bike ${Math.floor(s.battery)}% · Hull ${Math.floor(s.hp)}% · ${s.upgrade?'Motor upgraded':'Standard motor'}</p><button class="primary" data-panel="play">KEEP EXPLORING</button> <button data-panel="restart">NEW EXPEDITION</button>`;
else if(screen==='dead')html=`<div class="eyebrow">HELMET LINK LOST</div><h1>RUN<br><span>ENDED</span></h1><p class="lead">Your hull failed. Scout hostile positions with the drone, use the trail to avoid patrols, and repair damage with salvaged steel.</p><button class="primary" data-panel="restart">RESTART EXPEDITION</button>`;
else html=`<div class="eyebrow">EXPEDITION PAUSED</div><h1>HOLD<br><span>POSITION</span></h1><p>WASD move · Mouse / arrows look · F bike · Q drone<br>E interact · R scan · I pack / craft · M map<br>Click / X ballistic shot (1 round) · C energy pulse (3% bike)<br>Space / Shift drone altitude · S regenerative braking</p><button class="primary" data-panel="play">RESUME</button> <button data-panel="restart">NEW EXPEDITION</button>`;
$('#panel').innerHTML=html;if(screen==='map')drawMap($('#bigmap'),true);}
$('#panel').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.craft)craft(b.dataset.craft);else if(b.dataset.drop){s.inv[b.dataset.drop]=Math.max(0,s.inv[b.dataset.drop]-1);renderPanel();}else if(b.dataset.panel==='play')play();else if(b.dataset.panel==='transfer'){if(s.drone<100&&spend(10)){s.drone=clamp(s.drone+50,0,100);renderPanel();}}else if(b.dataset.panel==='restart')location.reload();});$('#menuBtn').onclick=()=>open('pause');
function targets(){const a=[{kind:'camp',x:54,z:-94,y:1.7,label:'Talk to Mara'},{kind:'ev',x:-85,z:-284,y:1.7,label:`Harvest EV reserve · ${Math.floor(s.ev)}% remaining`},{kind:'solar',x:90,z:-413,y:1.7,label:s.controller?`Harvest solar storage · ${Math.floor(s.solarEnergy)}%`:'Solar controller missing · repair in inventory'},{kind:'grid',x:155,z:-730,y:1.7,label:!s.relay?'Cabinet locked · activate rooftop drone relay':!s.interface?'Grid coupler required · repair in inventory':`Harvest substation reserve · ${Math.floor(s.gridEnergy)}%`},{kind:'relay',x:166,z:-778,y:15,label:s.relay?'Relay active':'DRONE: activate isolation relay'},{kind:'tower',x:0,z:-1435,y:1.7,label:s.won?'Relay decoded · origin 147 km away':'Decode transmission · requires 8% bike'}];crates.forEach((c,i)=>{if(!c.done)a.push({kind:'crate',index:i,x:c.x,z:c.z,y:1.7,label:'Scavenge crate · '+Object.entries(c.items).map(([k,v])=>v+' '+k).join(', ')});});return a;}
function interact(){if(!nearest){toast('Move closer to a marked object.');return;}const t=nearest;if(s.mode==='drone'&&t.kind!=='relay'){toast('Return to your body to scavenge or harvest.');return;}if(t.kind==='camp'){if(!s.met){s.met=true;add({electronics:1,steel:2});}open('npc');}else if(t.kind==='crate'){const c=crates[t.index];let mass=Object.entries(c.items).reduce((v,[k,n])=>v+weights[k]*n,0);if(cargo()+mass>24){toast('Pack full. Craft or drop materials in inventory.');return;}add(c.items);c.done=true;c.mesh.visible=false;toast('Salvage secured. Open I / Pack to repair equipment.');}else if(t.kind==='relay'){if(s.mode!=='drone'){toast('Relay is above ground. Launch the drone.');return;}s.relay=true;toast('Substation charge cabinet unlocked.');radio('Remote isolation complete. Stored energy is available at the lower cabinet.');}else if(t.kind==='tower'){if(s.won){toast('Signal origin: 147 km. End of playable region.');return;}if(spend(8)){s.won=true;open('win');}}else{if(t.kind==='solar'&&!s.controller){toast('Find 2 wire + 2 electronics. Repair controller in I / Pack.');return;}if(t.kind==='grid'&&(!s.relay||!s.interface)){toast(!s.relay?'Fly the drone to the rooftop relay, 15 m above ground.':'Restore the grid coupler in your pack.');return;}const key={ev:'ev',solar:'solarEnergy',grid:'gridEnergy'}[t.kind];const n=Math.min(20,s[key],100-s.battery);if(n<=.01){toast(s.battery>=99.9?'Bike battery full.':'Source depleted. Find another reserve.');return;}s[key]-=n;s.battery+=n;s.temp+=n*.2;toast(`Recovered ${n.toFixed(0)}% bike charge. ${Math.floor(s[key])}% remains at source.`);if(t.kind==='solar')s.solar=true;}}
function returnDrone(){s.pos.copy(droneOrigin.pos);s.yaw=droneOrigin.yaw;s.pitch=0;s.mode=droneOrigin.mode;s.speed=0;droneOrigin=null;toast('Drone docked.');}
function action(a){if(paused)return;if(a==='inventory'||a==='map'){open(a);return;}if(a==='interact')interact();if(a==='bike'){if(s.mode==='drone')return;if(s.mode==='bike'){s.mode='foot';s.speed=0;bike.position.set(s.pos.x,0,s.pos.z);bike.rotation.y=s.yaw;s.pos.x+=2;toast('On foot. Stay near the bike to remount.');}else if(dist(bike.position.x,bike.position.z)<7){s.mode='bike';s.pos.set(bike.position.x,1.7,bike.position.z);toast('Bike mounted.');}else toast('Your bike is '+Math.round(dist(bike.position.x,bike.position.z)*2)+' m away.');}if(a==='drone'){if(s.mode==='drone')returnDrone();else if(s.drone<5)toast('Drone depleted. Transfer bike energy in your pack.');else{droneOrigin={pos:s.pos.clone(),yaw:s.yaw,mode:s.mode};s.mode='drone';s.pos.y=5;s.speed=0;toast('Drone online. Space rises / Shift descends. Q returns.');}}if(a==='scan'){if(s.mode==='drone'){if(s.drone<3){toast('Drone charge too low.');return;}s.drone-=3;}else if(!spend(1))return;s.scanned=true;toast('SCAN COMPLETE · power signatures and hostiles marked');}if(a==='fire'||a==='pulse')fire(a==='pulse');}
function fire(pulse=false){if(shotCooldown>0||s.mode==='drone')return;if(pulse){if(!spend(3))return;}else if(s.ammo<=0){toast('No ammunition. C fires a 3% energy pulse.');return;}else s.ammo--;shotCooldown=.35;flash=.07;const origin=s.pos.clone(),dir=new T.Vector3();camera.getWorldDirection(dir);let best=null,bestD=100;for(const e of enemies){if(e.hp<=0)continue;const p=new T.Vector3(e.x,1.6,e.z).sub(origin),d=p.length();if(d<bestD&&p.normalize().dot(dir)>.987&&!blocked(origin,e.x,e.z)){best=e;bestD=d;}}if(best){best.hp-=pulse?45:40;toast(best.hp<=0?'Raider down. Recovered 4 rounds + 1 electronics.':'Hit / raider wounded');if(best.hp<=0){s.ammo+=4;add({electronics:1});best.mesh.rotation.z=Math.PI/2;best.mesh.position.y=.3;}}const end=origin.clone().addScaledVector(dir,best?bestD:85);const g=new T.BufferGeometry().setFromPoints([origin.clone().add(new T.Vector3(0,-.25,0)),end]);const l=new T.Line(g,new T.LineBasicMaterial({color:pulse?0x91ffff:0xffe6a8}));scene.add(l);setTimeout(()=>{scene.remove(l);g.dispose();l.material.dispose();},80);}
function blocked(p,x,z){const dx=x-p.x,dz=z-p.z,d=Math.hypot(dx,dz);for(let t=2;t<d;t+=3){const xx=p.x+dx*t/d,zz=p.z+dz*t/d;if(solids.some(b=>Math.abs(xx-b.x)<b.w&&Math.abs(zz-b.z)<b.d))return true;}return false;}
function move(dx,dz){const x=clamp(s.pos.x+dx,-600,600),z=clamp(s.pos.z+dz,-1600,230);if(s.mode==='drone'){s.pos.x=x;s.pos.z=z;return;}if(!solids.some(b=>Math.abs(x-b.x)<b.w&&Math.abs(s.pos.z-b.z)<b.d))s.pos.x=x;else s.speed*=.3;if(!solids.some(b=>Math.abs(s.pos.x-b.x)<b.w&&Math.abs(z-b.z)<b.d))s.pos.z=z;else s.speed*=.3;}
function update(dt){time+=dt;shotCooldown=Math.max(0,shotCooldown-dt);flash=Math.max(0,flash-dt);toastTimer-=dt;if(toastTimer<=0)$('#toast').style.display='none';if(keys.arrowleft)s.yaw+=dt*1.5;if(keys.arrowright)s.yaw-=dt*1.5;if(keys.arrowup)s.pitch=clamp(s.pitch+dt,-1.2,1.2);if(keys.arrowdown)s.pitch=clamp(s.pitch-dt,-1.2,1.2);
const forward=(keys.w?1:0)-(keys.s?1:0),turn=(keys.d?1:0)-(keys.a?1:0),road=Math.abs(s.pos.x)<12;let dx=0,dz=0;
if(s.mode==='bike'){s.yaw-=turn*dt*(.5+Math.min(Math.abs(s.speed)/15,1));let target=forward>0&&s.battery>0?(road?30:20):forward<0?-4:0;if(forward<0&&s.speed>1){s.battery=clamp(s.battery+dt*.035,0,100);target=0;}s.speed+=(target-s.speed)*Math.min(1,dt*(forward<0?2:.6));if(s.battery<=0)s.speed*=Math.max(0,1-dt);dx=-Math.sin(s.yaw)*s.speed*dt;dz=-Math.cos(s.yaw)*s.speed*dt;let travel=Math.hypot(dx,dz);s.battery=Math.max(0,s.battery-travel*.065*(road?1:1.4)*(1+cargo()/50)*(s.upgrade?.7:1));s.temp+=((24+Math.abs(s.speed)*1.3)-s.temp)*dt*.05;move(dx,dz);bike.position.set(s.pos.x,0,s.pos.z);bike.rotation.y=s.yaw;s.pos.y=1.7+Math.sin(time*(road?8:17))*Math.abs(s.speed)*.0018;
}else{let v=s.mode==='drone'?24:5;dx=(-Math.sin(s.yaw)*forward+Math.cos(s.yaw)*turn)*v*dt;dz=(-Math.cos(s.yaw)*forward-Math.sin(s.yaw)*turn)*v*dt;if(forward&&turn){dx*=.707;dz*=.707;}move(dx,dz);s.speed=Math.hypot(dx,dz)/dt;if(s.mode==='drone'){s.pos.y=clamp(s.pos.y+((keys[' ']?1:0)-(keys.shift?1:0))*dt*12,2,90);s.drone=Math.max(0,s.drone-dt*.25);const range=s.pos.distanceTo(droneOrigin.pos);if(range>300||s.drone<=0){s.drone=Math.max(0,s.drone-8);returnDrone();toast('Failsafe return. Drone charge penalized.');}}else s.pos.y=1.7;}
// Raiders defend their road section. Foot and drone reconnaissance reduce exposure.
enemyTimer-=dt;for(const e of enemies){if(e.hp<=0)continue;const player=s.mode==='drone'?droneOrigin.pos:s.pos;const d=Math.hypot(e.x-player.x,e.z-player.z);if(d<65&&d>10&&!blocked(player,e.x,e.z)){e.x+=(player.x-e.x)/d*dt*3;e.z+=(player.z-e.z)/d*dt*3;}else if(d>=65){e.x+=Math.sin(time*.3+e.home[0])*dt*.4;}e.mesh.position.set(e.x,0,e.z);e.mesh.lookAt(player.x,0,player.z);if(d<45&&!blocked(player,e.x,e.z)&&enemyTimer<=0){s.hp-=7;$('#damage').style.opacity='.3';setTimeout(()=>$('#damage').style.opacity='0',150);toast('Taking fire! Break line of sight or return fire.');enemyTimer=1.4;}}if(s.hp<=0&&!s.dead){s.dead=true;open('dead');}
nearest=null;let nd=8;for(const t of targets()){const d=Math.hypot(s.pos.x-t.x,s.pos.z-t.z,s.pos.y-t.y);if(d<nd){nd=d;nearest=t;}}$('#interaction').style.display=nearest?'block':'none';if(nearest)$('#interaction').textContent='[ E / USE ] '+nearest.label;
}
function drawMap(canvas,big=false){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#091d23';ctx.fillRect(0,0,w,h);const scale=big?.29:.19;const cx=big?0:s.pos.x,cz=big?-680:s.pos.z;const point=(x,z)=>[w/2+(x-cx)*scale,h/2+(z-cz)*scale];ctx.strokeStyle='#51767530';ctx.lineWidth=1;for(let x=0;x<w;x+=25){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}for(let y=0;y<h;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}ctx.strokeStyle='#81938a';ctx.lineWidth=big?5:3;ctx.beginPath();ctx.moveTo(...point(0,230));ctx.lineTo(...point(0,-1600));ctx.stroke();ctx.strokeStyle='#91a06066';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(...point(95,230));ctx.lineTo(...point(95,-1600));ctx.stroke();sites.filter(p=>p.id!=='relay').forEach(p=>{const [x,y]=point(p.x,p.z);ctx.strokeStyle='#dceba0';ctx.beginPath();ctx.arc(x,y,big?5:3,0,Math.PI*2);ctx.stroke();if(big){ctx.fillStyle='#c8d9bf';ctx.font='12px monospace';ctx.fillText(p.name,x+12,y+4);}});if(s.scanned)enemies.filter(e=>e.hp>0).forEach(e=>{ctx.fillStyle='#ed9374';const [x,y]=point(e.x,e.z);ctx.fillRect(x-3,y-3,6,6);});if(s.mode!=='bike'){ctx.fillStyle='#8adbd8';const [x,y]=point(bike.position.x,bike.position.z);ctx.fillRect(x-2,y-2,4,4);}const [x,y]=point(s.pos.x,s.pos.z);ctx.save();ctx.translate(x,y);ctx.rotate(-s.yaw);ctx.fillStyle='#f0f5ca';ctx.beginPath();ctx.moveTo(0,-6);ctx.lineTo(4,5);ctx.lineTo(-4,5);ctx.fill();ctx.restore();if(big){ctx.fillStyle='#92aaa6';ctx.font='12px monospace';ctx.fillText('N ↑',18,25);ctx.fillText('YOU / '+s.mode.toUpperCase(),18,h-18);}}
let hudTick=0;function hud(){const road=Math.abs(s.pos.x)<12;$('#speed').textContent=String(Math.round(Math.abs(s.speed)*2.237)).padStart(2,'0');$('#bikeValue').textContent=Math.floor(s.battery)+'%';$('#bikeBar').style.width=s.battery+'%';$('#bikeBar').style.background=s.battery<20?'#efb876':'#e8f18c';$('#droneValue').textContent=Math.floor(s.drone)+'%';$('#droneBar').style.width=s.drone+'%';$('#range').textContent='EST. RANGE '+(s.battery/(.065*(1+cargo()/50)*(s.upgrade?.7:1))*2/1000).toFixed(1)+' KM';$('#droneStatus').textContent=s.mode==='drone'?'SIGNAL '+Math.max(0,Math.round(100-s.pos.distanceTo(droneOrigin.pos)/3))+'%':'DOCKED · Q TO LAUNCH';$('#mode').textContent=s.mode.toUpperCase()+' / '+(s.mode==='drone'?'RECON LINK':'ONLINE');$('#health').textContent='HULL '+Math.max(0,Math.floor(s.hp))+'%';$('#temp').textContent='MOTOR '+Math.floor(s.temp)+'°C';$('#cargo').textContent='CARGO '+cargo().toFixed(1)+' KG';$('#terrain').textContent=road?'ASPHALT / EFFICIENCY 100%':'OFF ROAD / EFFICIENCY 71%';$('#signal').textContent='GRID SIGNAL · '+(dist(0,-1439)<300?'STRONG':s.scanned?'TRACKING':'WEAK');$('#questDistance').textContent=s.won?'NEW ORIGIN · 147 KM':'RELAY TOWER · '+(dist(0,-1439)*2/1000).toFixed(2)+' KM';$('#objective').textContent=s.won?'The signal continues beyond this region.':s.battery>dist(0,-1439)*.065*(1+cargo()/50)*(s.upgrade?.7:1)+8?'Enough charge. Reach and decode the radio tower.':s.met?'Scavenge, repair, and harvest. Then ride north.':'Find usable energy. Mara’s camp is nearby.';const deg=(((-s.yaw*180/Math.PI)%360)+360)%360,dirs=['N','NE','E','SE','S','SW','W','NW'];$('#compass').innerHTML='─── '+dirs[(Math.round(deg/45)+7)%8]+' ── <b>'+dirs[Math.round(deg/45)%8]+'</b> ── '+dirs[(Math.round(deg/45)+1)%8]+' ───';
for(const p of sites){const d=dist(p.x,p.z),v=new T.Vector3(p.x,p.y,p.z);const forward=new T.Vector3();camera.getWorldDirection(forward);const facing=v.clone().sub(camera.position).dot(forward)>0;v.project(camera);const visible=facing&&v.z<1&&Math.abs(v.x)<.94&&Math.abs(v.y)<.85&&(p.id==='tower'||d<190||s.scanned)&&(p.id!=='relay'||s.mode==='drone');p.el.style.display=visible?'block':'none';if(visible){p.el.style.left=(v.x*.5+.5)*innerWidth+'px';p.el.style.top=(-v.y*.5+.5)*innerHeight+'px';p.el.innerHTML='<strong>◇</strong>'+p.name+'<small>'+Math.round(d*2)+' M'+(s.scanned&&['ev','solar','grid'].includes(p.id)?' / POWER SIGNATURE':'')+'</small>';}}drawMap($('#minimap'));}
function loop(now){requestAnimationFrame(loop);const dt=Math.min((now-last)/1000,.04);last=now;if(!paused)update(dt);camera.position.copy(s.pos);camera.rotation.set(s.pitch,s.yaw,s.mode==='bike'?-((keys.d?1:0)-(keys.a?1:0))*Math.min(s.speed*.002,.05):0,'YXZ');cockpit.visible=s.mode==='bike';bike.visible=s.mode!=='bike';camera.updateMatrixWorld();for(const r of turbines)r.rotation.z+=dt*.22;beacon.material.color.setHex(Math.sin(now*.003)>0?0xffbd81:0x89554c);if(now-hudTick>100){hud();hudTick=now;}renderer.render(scene,camera);}renderPanel();requestAnimationFrame(loop);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
const bindings={e:'interact',f:'bike',q:'drone',r:'scan',i:'inventory',m:'map',x:'fire',c:'pulse'};window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'){if(!paused)open('pause');return;}keys[k]=true;if(!e.repeat&&bindings[k])action(bindings[k]);});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={};if(!paused)open('pause');});document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&!paused&&matchMedia('(pointer:fine)').matches)open('pause');});let dragging=false,px=0,py=0;$('#world').addEventListener('pointerdown',e=>{if(paused)return;if(e.pointerType==='touch'){dragging=true;px=e.clientX;py=e.clientY;$('#world').setPointerCapture(e.pointerId);}else if(document.pointerLockElement)action('fire');else $('#world').requestPointerLock?.()?.catch?.(()=>{});});$('#world').addEventListener('pointerup',()=>dragging=false);$('#world').addEventListener('pointercancel',()=>dragging=false);document.addEventListener('pointermove',e=>{if(paused)return;let dx=0,dy=0;if(document.pointerLockElement){dx=e.movementX;dy=e.movementY;}else if(dragging){dx=e.clientX-px;dy=e.clientY-py;px=e.clientX;py=e.clientY;}s.yaw-=dx*.003;s.pitch=clamp(s.pitch-dy*.0025,-1.2,1.2);});document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act));document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys[b.dataset.key]=false);});
